def detect_regions(grid):
    H, W = len(grid), len(grid[0])

    row_seps = [r for r in range(H) if all(grid[r][c] == 8 for c in range(W))]
    row_regs = []
    prev = -1
    for r in row_seps:
        if prev >= 0:
            row_regs.append((prev + 1, r - 1))
        prev = r
    if prev < H - 1:
        row_regs.append((prev + 1, H - 1))

    col_seps = [c for c in range(W) if all(grid[r][c] == 8 for r in range(H))]
    col_regs = []
    prev = -1
    for c in col_seps:
        if prev >= 0:
            col_regs.append((prev + 1, c - 1))
        prev = c
    if prev < W - 1:
        col_regs.append((prev + 1, W - 1))

    return row_regs, col_regs

